package ro.leo.visual;
import ro.leo.i18n.L;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import android.graphics.Typeface;import com.jcraft.jsch.*;import java.io.*;import java.util.*;import org.json.*;
public final class SshActivity extends PocketActivity {
 private PocketSsh ssh;private String host,user,remote="";private int port;private char[] password;private TextView output;private EditText command;private ScrollView terminalScroll;private final StringBuilder transcript=new StringBuilder();private final Handler updates=new Handler();private File last;
 protected void render()throws Exception{if(ssh!=null&&ssh.connected()){connected();return;}JSONObject profile=PocketStore.read(this,"ssh-profile");host=profile.optString("host","");user=profile.optString("user","");port=profile.optInt("port",22);LinearLayout f=fields("SSH / SFTP");final EditText address=field(f,L.t("Server"),host,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI),login=field(f,L.t("Utilizator"),user,InputType.TYPE_CLASS_TEXT),number=field(f,"Port",String.valueOf(port),InputType.TYPE_CLASS_NUMBER),secret=field(f,L.t("Parolă"),"",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);secret.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);left=new Runnable(){public void run(){try{host=address.getText().toString().trim();user=login.getText().toString().trim();port=Integer.parseInt(number.getText().toString());clearPassword();password=secret.getText().toString().toCharArray();secret.setText("");connect();}catch(Exception e){notice(e.getMessage());}}};back=new Runnable(){public void run(){finish();}};footer(L.t("Conectează"),"",L.t("Șterge"));address.requestFocus();}
 private void clearPassword(){if(password!=null)Arrays.fill(password,'\0');password=null;}
 private void connect(){if(ssh==null)ssh=new PocketSsh(this);final Exception[] failure={null};job(L.t("Conectare SSH"),new Work(){public void run(){try{ssh.connect(host,port,user,password==null?new char[0]:password);}catch(Exception e){failure[0]=e;}}},new Runnable(){public void run(){if(failure[0]!=null){if(ssh.repo!=null&&ssh.repo.candidate!=null&&!ssh.repo.changed){try{String fingerprint=PocketSsh.fingerprint(android.util.Base64.decode(ssh.repo.candidate.getKey(),android.util.Base64.DEFAULT));page(L.t("Verifică serverul SSH"),host+":"+port+"\n\n"+fingerprint+"\n\n"+L.t("Compară amprenta cu cea afișată de server înainte de a accepta."),goHome(),L.t("Încredere"),new Runnable(){public void run(){options(L.t("Accepți cheia serverului?"),new String[]{L.t("Anulează"),L.t("Salvează cheia și reconectează")},new Choice(){public void pick(int at){if(at==1)try{ssh.repo.trust();connect();}catch(Exception e){problem(e);}else{clearPassword();home();}}});}});}catch(Exception e){problem(e);}return;}clearPassword();problem(ssh.repo!=null&&ssh.repo.changed?new IOException("HOST KEY CHANGED. Connection refused."):failure[0]);return;}clearPassword();try{PocketStore.write(SshActivity.this,"ssh-profile",new JSONObject().put("host",host).put("user",user).put("port",port));}catch(Exception ignored){}remote="";connected();}});}
 private void connected(){list("SSH · "+host,Arrays.asList(L.t("Terminal SSH"),L.t("Fișiere SFTP"),L.t("Deconectează")),0,new Choice(){public void pick(int at){if(at==0)terminal();else if(at==1)files();else{ssh.close();home();}}},"",null);back=new Runnable(){public void run(){finish();}};}
 private void append(final String value){synchronized(transcript){transcript.append(value.replaceAll("\\x1B\\[[0-9;?]*[ -/]*[@-~]","").replaceAll("\\x1B[^\\x1B]{0,2}",""));if(transcript.length()>32768)transcript.delete(0,transcript.length()-32768);}updates.removeCallbacks(draw);updates.postDelayed(draw,60);}
 private final Runnable draw=new Runnable(){public void run(){if(output!=null&&!isFinishing()){synchronized(transcript){output.setText(transcript.toString());}if(terminalScroll!=null)terminalScroll.fullScroll(View.FOCUS_DOWN);}}};
 private void terminal(){begin(L.t("Terminal SSH"));terminalScroll=new ScrollView(this);output=text("",13);output.setTypeface(Typeface.MONOSPACE);terminalScroll.addView(output);root.addView(terminalScroll,new LinearLayout.LayoutParams(-1,0,1));command=new EditText(this);command.setTextColor(-1);command.setSingleLine(true);command.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);command.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING);root.addView(command);form=true;command.setOnKeyListener(new View.OnKeyListener(){public boolean onKey(View v,int key,KeyEvent e){if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getAction()==0&&e.getRepeatCount()==0){final String line=command.getText().toString();command.setText("");worker.execute(new Runnable(){public void run(){try{ssh.send(line+"\n");}catch(Exception err){append("\n"+err.getMessage());}}});}return true;}return false;}});left=new Runnable(){public void run(){options("SSH",new String[]{"Ctrl+C",L.t("Înapoi la sesiune"),L.t("Deconectează")},new Choice(){public void pick(int at){if(at==0)worker.execute(new Runnable(){public void run(){try{ssh.send("\u0003");}catch(Exception e){append(e.getMessage());}}});else if(at==1)connected();else{ssh.close();home();}}});}};back=new Runnable(){public void run(){connected();}};footer(L.t("Opțiuni"),L.t("Execută"),L.t("Șterge"));command.requestFocus();draw.run();worker.execute(new Runnable(){public void run(){try{ssh.startShell(new PocketSsh.Output(){public void text(String value){append(value);}});}catch(Exception e){append(e.getMessage());}}});}
 private void files(){final ArrayList<ChannelSftp.LsEntry> entries=new ArrayList<>();job(L.t("Citesc SFTP"),new Work(){public void run()throws Exception{ChannelSftp c=ssh.files();if(remote.isEmpty())remote=c.pwd();c.ls(remote,new ChannelSftp.LsEntrySelector(){public int select(ChannelSftp.LsEntry e){String n=e.getFilename();if(!n.equals(".")&&!n.contains("/")&&!n.contains("\\"))entries.add(e);return entries.size()>=1000?BREAK:CONTINUE;}});}},new Runnable(){public void run(){ArrayList<String> labels=new ArrayList<>();for(ChannelSftp.LsEntry e:entries)labels.add((e.getAttrs().isDir()?"▣ ":"↓ ")+e.getFilename()+"\n"+e.getAttrs().getSize()+" B");list("SFTP · "+remote,labels,0,new Choice(){public void pick(final int at){final ChannelSftp.LsEntry e=entries.get(at);if(e.getAttrs().isDir()){remote=(remote.endsWith("/")?remote:remote+"/")+e.getFilename();files();}else if(e.getAttrs().isLink())notice(L.t("Legătura simbolică nu este descărcată"));else options(L.t("Descarci fișierul?"),new String[]{L.t("Anulează"),L.t("Descarcă")},new Choice(){public void pick(int yes){if(yes==1){final String path=remote+"/"+e.getFilename();job(L.t("Descarc prin SFTP"),new Work(){public void run()throws Exception{last=PocketStore.output(SshActivity.this,"SFTP",e.getFilename());ssh.get(path,last);}},new Runnable(){public void run(){exported(last);}});}}});}},L.t("Încarcă fișier"),new Runnable(){public void run(){chooseFile("*",1);}});back=new Runnable(){public void run(){connected();}};}});}
 protected void selectedFile(int request,final File file){final String path=(remote.endsWith("/")?remote:remote+"/")+"leo-"+UUID.randomUUID().toString().substring(0,8)+"-"+file.getName();options(L.t("Încarci pe server?"),new String[]{L.t("Anulează"),L.t("Încarcă")+" · "+file.getName()},new Choice(){public void pick(int yes){if(yes==1)job(L.t("Încarc prin SFTP"),new Work(){public void run()throws Exception{ssh.put(file,path);}},new Runnable(){public void run(){files();}});}});}
 protected void onDestroy(){updates.removeCallbacksAndMessages(null);clearPassword();if(ssh!=null)ssh.close();super.onDestroy();}
}
